(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.RideView=factory()})(typeof globalThis!=='undefined'?globalThis:this,function(){
 const places=['澳门科技大学 TIS','澳门科技大学 R 座','澳门科技大学 A 座','擎天汇','横琴口岸'];
 const aliases={'A':places[2],'A座':places[2],'科大A座':places[2],'澳科大A座':places[2],'R':places[1],'R座':places[1],'科大R座':places[1],'澳科大R座':places[1],'TIS':places[0],'国际学校':places[0],'横琴':places[4],'横琴口岸（澳门侧）':places[4]};
 const normalize=v=>{const s=String(v||'').trim();return Object.prototype.hasOwnProperty.call(aliases,s)?aliases[s]:s};
 const short=v=>normalize(v).replace('澳门科技大学 ','科大 ');
 const active=r=>['gathering','ready','going'].includes(r.state);
 const settled=r=>!!r.bill&&r.bill.items.every(m=>m.status==='received');
 function task(r,uid){if(r.state!=='completed')return null;if(!r.bill)return {label:'待分摊',action:'发起分摊',kind:'create'};const me=r.bill.items.find(m=>m.id===uid);if(r.bill.payer===uid&&!settled(r))return {label:'待收齐',action:'查看收款进度',kind:'bill'};if(me&&me.status==='pending')return {label:'待转账',action:'查看我的份额',kind:'bill'};if(me&&me.status==='reported')return {label:'待确认到账',action:'查看费用单',kind:'bill'};return null}
 function status(r,uid){if(r.offer)return r.offer.confirmed.includes(uid)?'等待伙伴确认':'待你确认';if(active(r))return r.members?.length>1?'正在集合':'寻找同行';if(r.state==='completed')return settled(r)?'已结清':'集合已完成';return {cancelled:'已取消',timeout:'集合超时'}[r.state]||'已结束'}
 function matches(rows,from,to,at){return rows.filter(r=>normalize(r.from)===normalize(from)&&normalize(r.to)===normalize(to)&&Math.abs(r.departAt-at)<=900000).sort((a,b)=>Math.abs(a.departAt-at)-Math.abs(b.departAt-at))}
 function search(query,recents=[]){const q=String(query||'').trim(),normalized=normalize(q);return [...new Set([...recents,...places])].filter(p=>!q||normalize(p)===normalized||p.toLowerCase().includes(q.toLowerCase())||short(p).toLowerCase().includes(q.toLowerCase()))}
 function shares(value,members){const raw=String(value);if(!/^\d{1,4}(\.\d{1,2})?$/.test(raw))return [];const total=Math.round(Number(raw)*100);if(total<1||total>999900||!members.length)return [];return members.map((m,i)=>({...m,cents:Math.floor(total/members.length)+(i<total%members.length?1:0),amount:(Math.floor(total/members.length)+(i<total%members.length?1:0))/100})).map(m=>({...m,amountText:m.amount.toFixed(2)}))}
 function meeting(r){return r.point&&!r.point.includes('请在聊天')?r.point:'集合点待约定，请先在群里确认'}
 return {places,normalize,short,active,settled,task,status,matches,search,shares,meeting};
});

